    /// <para>Binds <c>SDL_hid_get_input_report</c>.</para>
    /// <para>
    /// Set the first byte of <c>data</c> to the Report ID of the report to be read. Make sure to allow space for this
    /// extra byte in <c>data</c>. Upon return, the first byte will still contain the Report ID, and the report data
    /// will start in data[1].
    /// </para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="dev">a device handle returned from SDL_hid_open().</param>
    /// <param name="data">
    /// a buffer to put the read data into, including the Report ID. Set the first byte of <c>data</c> to the Report ID
    /// of the report to be read, or set it to zero if your device does not use numbered reports.
    /// </param>
    /// <returns>
    /// the number of bytes read plus one for the report ID (which is still in the first byte), or -1 on on failure;
    /// call SDL_GetError() for more information.
    /// </returns>
    public static int HidGetInputReport(HidDevice dev, Span<byte> data)
    {
        fixed (byte* dataPtr = data)
        {
            return HidGetInputReport(dev, dataPtr, (nuint)data.Length);
        }
    }

